def gen(rng):
    def make(n, d, base):
        a = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == 0 and j == 0:
                    a[i][j] = base
                else:
                    m = max(a[i - 1][j] if i else -10**9, a[i][j - 1] if j else -10**9)
                    a[i][j] = m + rng.randint(0, d)
        return a
    def fmt(a, qs):
        n = len(a)
        return f"{n} {len(qs)}\n" + '\n'.join(' '.join(map(str, r)) for r in a) + '\n' + '\n'.join(map(str, qs))
    def queries(a, q):
        flat = [x for r in a for x in r]
        lo, hi = min(flat), max(flat)
        qs = []
        for _ in range(q):
            if rng.random() < 0.5:
                qs.append(rng.choice(flat))
            else:
                qs.append(rng.randint(lo - 2, hi + 2))
        return qs
    tests = []
    a = [[-5]]
    tests.append(fmt(a, [-5, 0]))
    a = [[7]]
    tests.append(fmt(a, [7]))
    a = [[1, 1], [1, 1]]
    tests.append(fmt(a, [1, 0, 2]))
    a = [[1, 2], [2, 3]]
    tests.append(fmt(a, [1, 2, 3, 4, 0]))
    for n in (2, 3, 4, 5, 6):
        for d in (0, 1, 3):
            a = make(n, d, rng.randint(-5, 0))
            tests.append(fmt(a, queries(a, rng.randint(1, 6))))
    for _ in range(4):
        a = make(5, 2, rng.randint(-5, 5))
        tests.append(fmt(a, queries(a, 8)))
    a = make(500, 90, rng.randint(-1000, 0))
    tests.append(fmt(a, queries(a, 1000)))
    a = make(500, 1, rng.randint(-1000, 0))
    tests.append(fmt(a, queries(a, 1000)))
    a = make(500, 30, -10**6)
    tests.append(fmt(a, queries(a, 1000)))
    a = make(300, 90, 0)
    tests.append(fmt(a, queries(a, 1000)))
    return tests

